<?php
require_once __DIR__ . '/../lib/bootstrap.php'; require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$t=post_string('title',150);if($t){$s=db()->prepare('INSERT INTO subjects(title,code,description,created_by) VALUES(?,?,?,?)');$s->execute([$t,post_string('code',50),post_string('description'),current_user()['id']]);flash('success','درس ایجاد شد.');}else flash('error','عنوان درس الزامی است.');redirect('teacher/subjects.php');}
if(current_user()['role']==='admin'){$subjects=db()->query("SELECT s.*,u.full_name creator FROM subjects s JOIN users u ON u.id=s.created_by WHERE s.is_active=1 ORDER BY s.id DESC")->fetchAll();}else{$teacherId=(int)current_user()['id'];$subjectStmt=db()->prepare("SELECT DISTINCT s.*,u.full_name creator FROM subjects s JOIN users u ON u.id=s.created_by WHERE s.is_active=1 AND (s.created_by=? OR EXISTS (SELECT 1 FROM class_subjects cs JOIN teacher_classes tc ON tc.class_id=cs.class_id WHERE cs.subject_id=s.id AND cs.teacher_id=? AND tc.teacher_id=?)) ORDER BY s.id DESC");$subjectStmt->execute([$teacherId,$teacherId,$teacherId]);$subjects=$subjectStmt->fetchAll();}$classes=db()->query('SELECT id,title FROM classes ORDER BY title')->fetchAll();$title='مدیریت درس‌ها';require __DIR__.'/../partials/header.php';?><h1>درس‌ها</h1><div class="card"><form method="post" class="grid grid-2"><?=csrf_field()?><div class="form-group"><label>عنوان درس</label><input name="title" required></div><div class="form-group"><label>کد درس</label><input name="code"></div><div class="form-group"><label>توضیحات</label><textarea name="description"></textarea></div><div><button class="btn btn-primary">افزودن درس</button></div></form></div><div class="card table-wrap"><table class="table"><thead><tr><th>عنوان</th><th>کد</th><th>ایجادکننده</th><th>عملیات</th></tr></thead><tbody><?php foreach($subjects as $s):?><tr><td><?=e($s['title'])?></td><td><?=e($s['code'])?></td><td><?=e($s['creator'])?></td><td><a class="btn btn-sm btn-primary" href="<?=e(url('teacher/exams.php?subject_id='.$s['id']))?>">ساخت آزمون</a></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
